const nodes = ($json.data && $json.data.comments && $json.data.comments.nodes) || [];
const byIssue = {};

for (const c of nodes) {
  if (!c.issue) continue;
  const k = c.issue.id;
  if (!byIssue[k]) {
    byIssue[k] = { identifier: c.issue.identifier, title: c.issue.title, url: c.issue.url, count: 0, deployments: new Set() };
  }
  byIssue[k].count += 1;
  const m = (c.body || '').match(/deployment:\s*([^·\n]+)/);
  if (m) byIssue[k].deployments.add(m[1].trim());
}

return Object.values(byIssue)
  .sort((a, b) => b.count - a.count)
  .slice(0, 10)
  .map((i, idx) => ({
    json: {
      rank: idx + 1,
      identifier: i.identifier,
      title: i.title,
      url: i.url,
      count: i.count,
      deployments: [...i.deployments].join(', '),
    },
  }));

const items = $input.all().map((i) => i.json);
if (!items.length) return [];

const lines = items.map((i) =>
  `${i.rank}. <${i.url}|${i.identifier}> ${i.title} - *${i.count}×* this week${i.deployments ? ` (${i.deployments})` : ''}`
);

const weekOf = new Date().toISOString().slice(0, 10);

return [{
  json: {
    text: `:repeat: *Top recurring deployment issues - week of ${weekOf}*\n\n${lines.join('\n')}\n\n_Counted from [occurrence] comments filed by deploykit triage. A bug seen once is an anomaly; these were not seen once._`,
  },
}];
